    private void update(){try{plot.first=f.trim().isEmpty()?null:new NumericExpression(f);plot.second=g.trim().isEmpty()?null:new NumericExpression(g);plot.kind=kind;caption.setText(kind+" · "+f+(g.isEmpty()?"":" ; "+g));plot.invalidate();chrome.invalidate();}catch(Exception e){ReferenceDialogs.builder(getContext()).setTitle("表达式错误").setMessage(e.getMessage()).setPositiveButton("修改",(d,w)->edit()).show();}}
    private void types(){ReferenceDialogs.builder(getContext()).setTitle("绘图类型").setItems(new String[]{"函数 y=f(x)","参数曲线 x(t),y(t)","极坐标 r(t)","隐式 F(x,y)=0"},(d,i)->{kind=new String[]{"函数","参数","极坐标","隐式"}[i];f=new String[]{"sin(x)","cos(t)","1+cos(t)","x^2+y^2-4"}[i];g=i==1?"sin(t)":"";plot.reset();update();edit();}).show();}
