    private void table(){if(plot.first==null){edit();return;}if(!kind.equals("函数")){message("数值表","数值表用于 y=f(x) 模式。");return;}parameters("数值表",new String[]{"起点","终点","步长"},new String[]{"0","5","0.5"},a->{double lo=Double.parseDouble(a[0]),hi=Double.parseDouble(a[1]),step=Double.parseDouble(a[2]);if(!Double.isFinite(lo)||!Double.isFinite(hi)||!Double.isFinite(step)||step==0||(hi-lo)/step<0||(hi-lo)/step>99)throw new IllegalArgumentException("最多 100 行，步长须指向终点");StringBuilder s=new StringBuilder("x         f(x)\n");int n=(int)Math.floor((hi-lo)/step+1e-10);for(int k=0;k<=n;k++){double x=lo+k*step;s.append(fmt(x)).append("    ").append(fmt(plot.first.value(x))).append('\n');}return s.toString();});}
