        int hit(float x,float y){if(y>=240&&y<348){if(x<130)return 1;if(x>=705&&x<825)return 2;if(x>=825&&x<960)return 3;if(x>=960)return 4;}if(y>=2232&&y<2358)return 10+Math.min(3,(int)(x/270));if(y>=2053&&y<=2208){int i=(int)((x-22)/163),count=tab==1?5:3;if(x>=22&&i>=0&&i<count&&x<=22+i*163+145)return 20+i;}if(x>=945&&x<=1059){if(y>=368&&y<483)return 30;if(y>=483&&y<598)return 31;if(y>=623&&y<737)return 32;if(y>=762&&y<876)return 33;}return -1;}
