        @Override public boolean onTouchEvent(MotionEvent e){zoom.onTouchEvent(e);int action=e.getActionMasked();if(action==MotionEvent.ACTION_DOWN){activePointer=e.getPointerId(0);lastX=e.getX();lastY=e.getY();return true;}if(action==MotionEvent.ACTION_POINTER_DOWN){activePointer=-1;return true;}if(action==MotionEvent.ACTION_POINTER_UP){int remaining=e.getActionIndex()==0?1:0;if(e.getPointerCount()==2){activePointer=e.getPointerId(remaining);lastX=e.getX(remaining);lastY=e.getY(remaining);}return true;}if(action==MotionEvent.ACTION_MOVE&&e.getPointerCount()==1&&!zoom.isInProgress()){int index=e.findPointerIndex(activePointer);if(index>=0){float x=e.getX(index),y=e.getY(index);cx-=(x-lastX)/units;cy+=(y-lastY)/(units*2);lastX=x;lastY=y;invalidate();}}if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL){activePointer=-1;if(action==MotionEvent.ACTION_UP)performClick();}return true;}

